\set ON_ERROR_STOP on
CREATE OR REPLACE FUNCTION private.is_restaurant_order_payment_status(p_status text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select lower(btrim(coalesce(p_status, ''))) in ('unpaid', 'paid', 'void')
$function$
;
